import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: montserratFamily } = loadMontserrat();



export type PopInSequenceProps = Record<string, any>;

const PopInSequence: React.FC<PopInSequenceProps> = ({
  backgroundColor = "#09172A",
  transparentBackground = false,
  durationInSeconds = 4,
  items = [
    {
      imageUrl: "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/a41aca29a8e4478cb07a11e325c8a1e3.png",
      label: "DATA",
      labelColor: "#ffffff",
    },
    {
      imageUrl: "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/c7d0888d4d72436eae8e4ff64d09df9a.png",
      label: "DECISION",
      labelColor: "#ffffff",
    },
    {
      imageUrl: "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/6f9680b079b7451084732efb52445ef0.png",
      label: "RISK",
      labelColor: "#ffffff",
    },
  ],
  itemGap = 60,
  labelMarginTop = 40,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Stagger the entrances evenly over the first half of the animation
  const staggerFrames = Math.floor((durationInSeconds * fps * 0.4) / Math.max(1, items.length));
  const baseStartFrame = 15;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          flex: 1,
          display: "flex",
          flexDirection: "row",
          justifyContent: "center",
          alignItems: "center",
          gap: itemGap * s,
          width: "100%",
          height: "100%",
        }}
      >
        {items.map((item, index) => {
          const startFrame = baseStartFrame + index * staggerFrames;

          const itemScale = spring({
            frame: frame - startFrame,
            fps,
            config: {
              damping: 14,
              stiffness: 110,
              mass: 0.8,
            },
          });

          const itemOpacity = interpolate(
            frame - startFrame,
            [0, 8],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Sub-element slight delay for a more organic pop
          const textOpacity = interpolate(
            frame - startFrame - 5,
            [0, 10],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={index}
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                opacity: frame < startFrame ? 0 : itemOpacity,
                transform: `scale(${itemScale})`,
                transition: "none",
                width: width * 0.25, // Assign a consistent column width
              }}
            >
              <div
                style={{
                  width: "100%",
                  height: height * 0.45,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  transition: "none",
                }}
              >
                <Img
                  src={item.imageUrl}
                  style={{
                    maxWidth: "100%",
                    maxHeight: "100%",
                    objectFit: "contain",
                    transition: "none",
                  }}
                />
              </div>
              
              <span
                style={{
                  fontFamily: montserratFamily,
                  fontSize: 68 * s,
                  fontWeight: 800,
                  color: item.labelColor,
                  marginTop: labelMarginTop * s,
                  letterSpacing: 3 * s,
                  opacity: frame < startFrame + 5 ? 0 : textOpacity,
                  transition: "none",
                }}
              >
                {item.label}
              </span>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default PopInSequence;